import React, { useEffect, useRef, useState } from 'react';
import * as d3 from 'd3';
import { geoPath, geoMercator } from 'd3-geo';
import './MapStyles.css';

function MapFour() {
    const mapRef = useRef(null);
    const tooltipRef = useRef(null);
    const [selectedCategory, setSelectedCategory] = useState('toutes');

    useEffect(() => {
        if (!mapRef.current) return;

        // Clear any existing SVG
        d3.select(mapRef.current).selectAll("*").remove();

        // Set up dimensions
        const width = 700;
        const height = 700;

        // Create SVG
        const svg = d3.select(mapRef.current)
            .append("svg")
            .attr("width", width)
            .attr("height", height);

        // Create tooltip
        const tooltip = d3.select(tooltipRef.current);

        // Set up projection for Benin
        const projection = geoMercator()
            .center([2.3, 9.5]) // Center of Benin
            .scale(5000)
            .translate([width / 2, height / 2]);

        // Set up path generator
        const path = geoPath().projection(projection);

        // Set up color scale for departments
        const colorDepartments = d3.scaleLinear()
            .domain([400000, 1400000]) // Population range
            .range(["#f7fcf5", "#00441b"]);
        
        // Set up color scale for categories
        const colorCategories = d3.scaleOrdinal()
            .domain(['Fruits', 'Légumes', 'Viandes', 'Poissons', 'Produits laitiers', 'Autres'])
            .range(d3.schemeCategory10);

        // Set up zoom behavior
        const zoom = d3.zoom()
            .scaleExtent([1, 8])
            .on("zoom", (event) => {
                svg.selectAll("path")
                    .attr("transform", event.transform);
                svg.selectAll("circle")
                    .attr("transform", event.transform);
                svg.selectAll("text")
                    .attr("transform", event.transform);
            });

        // Apply zoom to SVG
        svg.call(zoom);

        // Categories data
        const categories = [
            'Fruits', 'Légumes', 'Viandes', 'Poissons', 'Produits laitiers', 'Autres'
        ];

        // Function to get offset for category points
        function getOffset(category) {
            const baseOffset = 10;
            switch(category) {
                case 'Fruits':
                    return { x: -baseOffset, y: -baseOffset };
                case 'Légumes':
                    return { x: baseOffset, y: -baseOffset };
                case 'Viandes':
                    return { x: -baseOffset, y: baseOffset };
                case 'Poissons':
                    return { x: baseOffset, y: baseOffset };
                case 'Produits laitiers':
                    return { x: 0, y: -1.5 * baseOffset };
                case 'Autres':
                    return { x: 0, y: 1.5 * baseOffset };
                default:
                    return { x: 0, y: 0 };
            }
        }

        // Load data
        Promise.all([
            d3.json(process.env.PUBLIC_URL + '/json/benin/departements.geojson'),
            d3.json(process.env.PUBLIC_URL + '/json/benin/produits.geojson')
        ]).then(([departements, produits]) => {
            // Draw departments (base map)
            svg.selectAll('.departement')
                .data(departements.features)
                .enter()
                .append('path')
                .attr("d", path)
                .attr("class", "fond")
                .style("fill", "#f0f0f0")
                .attr("stroke", "#fff")
                .attr("stroke-width", 1);

            // Create category data points
            const categoryData = [];
            
            produits.features.forEach(feature => {
                // For each commune, create a point for each category
                categories.forEach(category => {
                    if (feature.properties.produits[category] > 0) {
                        categoryData.push({
                            ...feature,
                            category: category,
                            count: feature.properties.produits[category]
                        });
                    }
                });
            });

            // Draw category points
            displayCategoryPoints(categoryData, svg, projection, tooltip, colorCategories, getOffset, 'toutes');

        }).catch(error => {
            console.error("Error loading data:", error);
        });

        // Function to update category points based on selected category
        const updateCategoryPoints = (category) => {
            // Remove existing category points
            svg.selectAll('.category-point').remove();
            svg.selectAll('.commune-label').remove();

            d3.json(process.env.PUBLIC_URL + '/json/benin/produits.geojson')
                .then(produits => {
                    // Create category data points
                    const categoryData = [];
                    
                    produits.features.forEach(feature => {
                        if (category === 'toutes') {
                            // For each commune, create a point for each category
                            categories.forEach(cat => {
                                if (feature.properties.produits[cat] > 0) {
                                    categoryData.push({
                                        ...feature,
                                        category: cat,
                                        count: feature.properties.produits[cat]
                                    });
                                }
                            });
                        } else {
                            // Only include selected category
                            if (feature.properties.produits[category] > 0) {
                                categoryData.push({
                                    ...feature,
                                    category: category,
                                    count: feature.properties.produits[category]
                                });
                            }
                        }
                    });

                    displayCategoryPoints(categoryData, svg, projection, tooltip, colorCategories, getOffset, category);
                })
                .catch(error => console.error("Error loading data:", error));
        };

        // Function to display category points
        function displayCategoryPoints(data, svg, projection, tooltip, colorScale, getOffsetFn, selectedCategory) {
            // Draw category points
            svg.selectAll('.category-point')
                .data(data)
                .enter()
                .append('circle')
                .attr("cx", d => {
                    const coords = projection(d.geometry.coordinates);
                    const offset = getOffsetFn(d.category);
                    return coords[0] + offset.x;
                })
                .attr("cy", d => {
                    const coords = projection(d.geometry.coordinates);
                    const offset = getOffsetFn(d.category);
                    return coords[1] + offset.y;
                })
                .attr("r", d => Math.sqrt(d.count) * 2 + 3) // Size based on count
                .attr("class", "category-point")
                .style("fill", d => colorScale(d.category))
                .style("stroke", "#333")
                .style("stroke-width", 1)
                .style("opacity", 0.8)
                .on('mousemove', function(event, d) {
                    // Show tooltip
                    const [x, y] = d3.pointer(event);
                    tooltip.classed('hidden', false)
                        .style('left', (x + 20) + 'px')
                        .style('top', (y + 20) + 'px')
                        .html(`
                            <strong>${d.properties.name}</strong><br>
                            Département: ${d.properties.departement}<br>
                            Catégorie: ${d.category}<br>
                            Nombre de produits: ${d.count}
                        `);
                })
                .on('mouseout', function() {
                    // Hide tooltip
                    tooltip.classed('hidden', true);
                });

            // Add commune labels if showing a single category
            if (selectedCategory !== 'toutes') {
                // Get unique communes
                const uniqueCommunes = Array.from(new Set(data.map(d => d.properties.name)))
                    .map(name => {
                        const commune = data.find(d => d.properties.name === name);
                        return {
                            name: name,
                            coordinates: commune.geometry.coordinates
                        };
                    });

                svg.selectAll('.commune-label')
                    .data(uniqueCommunes)
                    .enter()
                    .append('text')
                    .attr("x", d => projection(d.coordinates)[0])
                    .attr("y", d => projection(d.coordinates)[1] - 15)
                    .attr("text-anchor", "middle")
                    .attr("class", "commune-label")
                    .style("font-size", "10px")
                    .style("font-weight", "bold")
                    .text(d => d.name);
            }
        }

        // Set up event listener for category change
        const handleCategoryChange = (e) => {
            setSelectedCategory(e.target.value);
            updateCategoryPoints(e.target.value);
        };

        // Expose the handler to the component
        window.handleCategoryChange = handleCategoryChange;

        // Cleanup function
        return () => {
            d3.select(mapRef.current).selectAll("*").remove();
            delete window.handleCategoryChange;
        };
    }, []);

    return (
        <div className="map-page">
            <div className="map-title">
                <h2>Catégories de produits au Bénin</h2>
            </div>

            <div className="map-controls">
                <label htmlFor="categorySelect">Catégorie: </label>
                <select
                    id="categorySelect"
                    value={selectedCategory}
                    onChange={(e) => window.handleCategoryChange && window.handleCategoryChange(e)}
                >
                    <option value="toutes">Toutes catégories</option>
                    <option value="Fruits">Fruits</option>
                    <option value="Légumes">Légumes</option>
                    <option value="Viandes">Viandes</option>
                    <option value="Poissons">Poissons</option>
                    <option value="Produits laitiers">Produits laitiers</option>
                    <option value="Autres">Autres</option>
                </select>
            </div>

            <div className="map-container" ref={mapRef}></div>
            <div className="tooltip hidden" ref={tooltipRef}></div>

            <div className="map-footer">
                <p>Carte des catégories de produits - Bénin</p>
            </div>
        </div>
    );
}

export default MapFour;