import React, { useEffect, useRef, useState } from 'react';
import * as d3 from 'd3';
import { geoPath, geoMercator } from 'd3-geo';
import './MapStyles.css';

function MapFive() {
    const mapRef = useRef(null);
    const tooltipRef = useRef(null);
    const [selectedCategory, setSelectedCategory] = useState('toutes');

    useEffect(() => {
        if (!mapRef.current) return;

        // Clear any existing SVG
        d3.select(mapRef.current).selectAll("*").remove();

        // Set up dimensions
        const width = 700;
        const height = 700;

        // Create SVG
        const svg = d3.select(mapRef.current)
            .append("svg")
            .attr("width", width)
            .attr("height", height);

        // Create tooltip
        const tooltip = d3.select(tooltipRef.current);

        // Set up projection for Benin
        const projection = geoMercator()
            .center([2.3, 9.5]) // Center of Benin
            .scale(5000)
            .translate([width / 2, height / 2]);

        // Set up path generator
        const path = geoPath().projection(projection);

        // Set up color scale for departments
        const colorDepartments = d3.scaleLinear()
            .domain([400000, 1400000]) // Population range
            .range(["#f7fcf5", "#00441b"]);
        
        // Set up color scale for categories
        const colorCategories = d3.scaleOrdinal()
            .domain(['Fruits', 'Légumes', 'Viandes', 'Poissons', 'Produits laitiers', 'Autres'])
            .range(d3.schemeCategory10);

        // Set up zoom behavior
        const zoom = d3.zoom()
            .scaleExtent([1, 8])
            .on("zoom", (event) => {
                svg.selectAll("path")
                    .attr("transform", event.transform);
                svg.selectAll("g.pie-chart")
                    .attr("transform", function(d) {
                        const coords = projection(d.geometry.coordinates);
                        return `translate(${coords[0]}, ${coords[1]}) scale(${1/event.transform.k})`;
                    });
                svg.selectAll("text.commune-label")
                    .attr("transform", event.transform);
            });

        // Apply zoom to SVG
        svg.call(zoom);

        // Categories data
        const categories = [
            'Fruits', 'Légumes', 'Viandes', 'Poissons', 'Produits laitiers', 'Autres'
        ];

        // Load data
        Promise.all([
            d3.json(process.env.PUBLIC_URL + '/json/benin/departements.geojson'),
            d3.json(process.env.PUBLIC_URL + '/json/benin/produits.geojson')
        ]).then(([departements, produits]) => {
            // Draw departments (base map)
            svg.selectAll('.departement')
                .data(departements.features)
                .enter()
                .append('path')
                .attr("d", path)
                .attr("class", "fond")
                .style("fill", "#f0f0f0")
                .attr("stroke", "#fff")
                .attr("stroke-width", 1);

            // Draw pie charts for each commune
            displayPieCharts(produits.features, svg, projection, tooltip, colorCategories, 'toutes');

        }).catch(error => {
            console.error("Error loading data:", error);
        });

        // Function to update pie charts based on selected category
        const updatePieCharts = (category) => {
            // Remove existing pie charts
            svg.selectAll('g.pie-chart').remove();
            svg.selectAll('text.commune-label').remove();

            d3.json(process.env.PUBLIC_URL + '/json/benin/produits.geojson')
                .then(data => {
                    displayPieCharts(data.features, svg, projection, tooltip, colorCategories, category);
                })
                .catch(error => console.error("Error loading data:", error));
        };

        // Function to display pie charts
        function displayPieCharts(data, svg, projection, tooltip, colorScale, selectedCategory) {
            // Create pie generator
            const pie = d3.pie()
                .value(d => d.value)
                .sort(null);
            
            // Create arc generator
            const arc = d3.arc()
                .innerRadius(0)
                .outerRadius(15);
            
            // Process data for pie charts
            data.forEach(feature => {
                // Extract category data
                const categoryData = [];
                
                if (selectedCategory === 'toutes') {
                    // Include all categories
                    Object.entries(feature.properties.produits).forEach(([category, count]) => {
                        if (count > 0) {
                            categoryData.push({
                                category: category,
                                value: count
                            });
                        }
                    });
                } else {
                    // Only include selected category
                    const count = feature.properties.produits[selectedCategory];
                    if (count > 0) {
                        categoryData.push({
                            category: selectedCategory,
                            value: count
                        });
                    }
                }
                
                // Only create pie chart if there's data
                if (categoryData.length > 0) {
                    // Create pie chart group
                    const pieGroup = svg.append("g")
                        .attr("class", "pie-chart")
                        .attr("transform", `translate(${projection(feature.geometry.coordinates)[0]}, ${projection(feature.geometry.coordinates)[1]})`)
                        .datum(feature) // Store original feature data
                        .on('mousemove', function(event, d) {
                            // Show tooltip
                            const [x, y] = d3.pointer(event, svg.node());
                            
                            // Create tooltip content
                            let tooltipContent = `<strong>${d.properties.name}</strong><br>Département: ${d.properties.departement}<br><br>`;
                            
                            if (selectedCategory === 'toutes') {
                                // Show all categories
                                Object.entries(d.properties.produits).forEach(([category, count]) => {
                                    if (count > 0) {
                                        tooltipContent += `${category}: ${count} produits<br>`;
                                    }
                                });
                            } else {
                                // Show only selected category
                                tooltipContent += `${selectedCategory}: ${d.properties.produits[selectedCategory]} produits`;
                            }
                            
                            tooltip.classed('hidden', false)
                                .style('left', (x + 20) + 'px')
                                .style('top', (y + 20) + 'px')
                                .html(tooltipContent);
                        })
                        .on('mouseout', function() {
                            // Hide tooltip
                            tooltip.classed('hidden', true);
                        });
                    
                    // Draw pie slices
                    pieGroup.selectAll('path')
                        .data(pie(categoryData))
                        .enter()
                        .append('path')
                        .attr('d', arc)
                        .attr('fill', d => colorScale(d.data.category))
                        .attr('stroke', '#fff')
                        .attr('stroke-width', 1);
                    
                    // Add commune label
                    svg.append('text')
                        .attr("x", projection(feature.geometry.coordinates)[0])
                        .attr("y", projection(feature.geometry.coordinates)[1] - 20)
                        .attr("text-anchor", "middle")
                        .attr("class", "commune-label")
                        .style("font-size", "10px")
                        .style("font-weight", "bold")
                        .text(feature.properties.name);
                }
            });
        }

        // Set up event listener for category change
        const handleCategoryChange = (e) => {
            setSelectedCategory(e.target.value);
            updatePieCharts(e.target.value);
        };

        // Expose the handler to the component
        window.handleCategoryChange = handleCategoryChange;

        // Cleanup function
        return () => {
            d3.select(mapRef.current).selectAll("*").remove();
            delete window.handleCategoryChange;
        };
    }, []);

    return (
        <div className="map-page">
            <div className="map-title">
                <h2>Répartition des produits par catégorie au Bénin</h2>
            </div>

            <div className="map-controls">
                <label htmlFor="categorySelect">Catégorie: </label>
                <select
                    id="categorySelect"
                    value={selectedCategory}
                    onChange={(e) => window.handleCategoryChange && window.handleCategoryChange(e)}
                >
                    <option value="toutes">Toutes catégories</option>
                    <option value="Fruits">Fruits</option>
                    <option value="Légumes">Légumes</option>
                    <option value="Viandes">Viandes</option>
                    <option value="Poissons">Poissons</option>
                    <option value="Produits laitiers">Produits laitiers</option>
                    <option value="Autres">Autres</option>
                </select>
            </div>

            <div className="map-container" ref={mapRef}></div>
            <div className="tooltip hidden" ref={tooltipRef}></div>

            <div className="map-footer">
                <p>Carte de répartition des produits - Bénin</p>
            </div>
            
            <div className="map-legend">
                <div className="legend-title">Légende</div>
                <div className="legend-item">
                    <span className="legend-color" style={{backgroundColor: d3.schemeCategory10[0]}}></span>
                    <span className="legend-label">Fruits</span>
                </div>
                <div className="legend-item">
                    <span className="legend-color" style={{backgroundColor: d3.schemeCategory10[1]}}></span>
                    <span className="legend-label">Légumes</span>
                </div>
                <div className="legend-item">
                    <span className="legend-color" style={{backgroundColor: d3.schemeCategory10[2]}}></span>
                    <span className="legend-label">Viandes</span>
                </div>
                <div className="legend-item">
                    <span className="legend-color" style={{backgroundColor: d3.schemeCategory10[3]}}></span>
                    <span className="legend-label">Poissons</span>
                </div>
                <div className="legend-item">
                    <span className="legend-color" style={{backgroundColor: d3.schemeCategory10[4]}}></span>
                    <span className="legend-label">Produits laitiers</span>
                </div>
                <div className="legend-item">
                    <span className="legend-color" style={{backgroundColor: d3.schemeCategory10[5]}}></span>
                    <span className="legend-label">Autres</span>
                </div>
            </div>
        </div>
    );
}

export default MapFive;