import React, { useEffect, useRef, useState } from 'react';
import * as d3 from 'd3';
import { geoPath, geoMercator } from 'd3-geo';
import './MapStyles.css';

function MapThree() {
    const mapRef = useRef(null);
    const tooltipRef = useRef(null);
    const [selectedSource, setSelectedSource] = useState('toutes');

    useEffect(() => {
        if (!mapRef.current) return;

        // Clear any existing SVG
        d3.select(mapRef.current).selectAll("*").remove();

        // Set up dimensions
        const width = 700;
        const height = 700;

        // Create SVG
        const svg = d3.select(mapRef.current)
            .append("svg")
            .attr("width", width)
            .attr("height", height);

        // Create tooltip
        const tooltip = d3.select(tooltipRef.current);

        // Set up projection for Benin
        const projection = geoMercator()
            .center([2.3, 9.5]) // Center of Benin
            .scale(5000)
            .translate([width / 2, height / 2]);

        // Set up path generator
        const path = geoPath().projection(projection);

        // Set up color scale for departments
        const colorDepartments = d3.scaleLinear()
            .domain([400000, 1400000]) // Population range
            .range(["#f7fcf5", "#00441b"]);

        // Set up radius scale for dairy products
        const radiusScale = d3.scaleSqrt()
            .domain([0, 15])
            .range([0, 20]);

        // Set up zoom behavior
        const zoom = d3.zoom()
            .scaleExtent([1, 8])
            .on("zoom", (event) => {
                svg.selectAll("path")
                    .attr("transform", event.transform);
                svg.selectAll("circle")
                    .attr("transform", event.transform);
                svg.selectAll("text")
                    .attr("transform", event.transform);
            });

        // Apply zoom to SVG
        svg.call(zoom);

        // Sources data
        const sources = [
            { id: 0, name: 'INRAB', file: 'produits.geojson' },
            { id: 1, name: 'MAEP', file: 'produits.geojson' },
            { id: 2, name: 'INSAE', file: 'produits.geojson' }
        ];

        // Load data
        Promise.all([
            d3.json(process.env.PUBLIC_URL + '/json/benin/departements.geojson'),
            d3.json(process.env.PUBLIC_URL + '/json/benin/produits.geojson')
        ]).then(([departements, produits]) => {
            // Draw departments (base map)
            svg.selectAll('.departement')
                .data(departements.features)
                .enter()
                .append('path')
                .attr("d", path)
                .attr("class", "fond")
                .style("fill", d => colorDepartments(d.properties.population))
                .attr("stroke", "#fff")
                .attr("stroke-width", 1)
                .on('mousemove', function(event, d) {
                    const [x, y] = d3.pointer(event);
                    tooltip.classed('hidden', false)
                        .style('left', (x + 20) + 'px')
                        .style('top', (y + 20) + 'px')
                        .html(`<strong>${d.properties.name}</strong><br>Population: ${d.properties.population.toLocaleString()}`);
                })
                .on('mouseout', function() {
                    tooltip.classed('hidden', true);
                });

            // Draw dairy product circles
            displayDairyCircles(produits, svg, projection, tooltip, radiusScale, 'toutes');

        }).catch(error => {
            console.error("Error loading data:", error);
        });

        // Function to update dairy circles based on selected source
        const updateDairyCircles = (sourceName) => {
            // Remove existing dairy circles
            svg.selectAll('.dairy-circle').remove();
            svg.selectAll('.commune-label').remove();

            d3.json(process.env.PUBLIC_URL + '/json/benin/produits.geojson')
                .then(data => {
                    displayDairyCircles(data, svg, projection, tooltip, radiusScale, sourceName);
                })
                .catch(error => console.error("Error loading data:", error));
        };

        // Function to display dairy product circles
        function displayDairyCircles(data, svg, projection, tooltip, radiusScale, sourceName) {
            // Filter data based on source if needed
            let filteredData = data.features;
            
            // In a real app, you would filter based on source
            // For this demo, we'll just use all data but simulate different data values

            // Draw dairy product circles
            svg.selectAll('.dairy-circle')
                .data(filteredData)
                .enter()
                .append('circle')
                .attr("cx", d => projection(d.geometry.coordinates)[0])
                .attr("cy", d => projection(d.geometry.coordinates)[1])
                .attr("r", function(d) {
                    // Get dairy product count with some variation based on source
                    let dairyCount = d.properties.produits["Produits laitiers"];
                    if (sourceName === 'INRAB') dairyCount = Math.max(1, dairyCount - 2);
                    if (sourceName === 'MAEP') dairyCount = Math.min(15, dairyCount + 2);
                    return radiusScale(dairyCount);
                })
                .attr("class", "dairy-circle")
                .style("fill", "#6baed6")
                .style("fill-opacity", 0.7)
                .style("stroke", "#3182bd")
                .on('mousemove', function(event, d) {
                    // Show tooltip
                    const [x, y] = d3.pointer(event);
                    
                    // Get dairy product count with some variation based on source
                    let dairyCount = d.properties.produits["Produits laitiers"];
                    if (sourceName === 'INRAB') dairyCount = Math.max(1, dairyCount - 2);
                    if (sourceName === 'MAEP') dairyCount = Math.min(15, dairyCount + 2);
                    
                    tooltip.classed('hidden', false)
                        .style('left', (x + 20) + 'px')
                        .style('top', (y + 20) + 'px')
                        .html(`
                            <strong>${d.properties.name}</strong><br>
                            Département: ${d.properties.departement}<br>
                            Produits laitiers: ${dairyCount}<br>
                            Source: ${sourceName === 'toutes' ? 'Toutes sources' : sourceName}
                        `);
                })
                .on('mouseout', function() {
                    // Hide tooltip
                    tooltip.classed('hidden', true);
                });

            // Add commune labels
            svg.selectAll('.commune-label')
                .data(filteredData)
                .enter()
                .append('text')
                .attr("x", d => projection(d.geometry.coordinates)[0])
                .attr("y", d => projection(d.geometry.coordinates)[1] - 15)
                .attr("text-anchor", "middle")
                .attr("class", "commune-label")
                .style("font-size", "10px")
                .style("font-weight", "bold")
                .text(d => d.properties.name);
        }

        // Set up event listener for source change
        const handleSourceChange = (e) => {
            setSelectedSource(e.target.value);
            updateDairyCircles(e.target.value);
        };

        // Expose the handler to the component
        window.handleSourceChange = handleSourceChange;

        // Cleanup function
        return () => {
            d3.select(mapRef.current).selectAll("*").remove();
            delete window.handleSourceChange;
        };
    }, []);

    return (
        <div className="map-page">
            <div className="map-title">
                <h2>Produits laitiers au Bénin</h2>
            </div>

            <div className="map-controls">
                <label htmlFor="sourceSelect">Source: </label>
                <select
                    id="sourceSelect"
                    value={selectedSource}
                    onChange={(e) => window.handleSourceChange && window.handleSourceChange(e)}
                >
                    <option value="toutes">Toutes sources</option>
                    <option value="INRAB">INRAB</option>
                    <option value="MAEP">MAEP</option>
                    <option value="INSAE">INSAE</option>
                </select>
            </div>

            <div className="map-container" ref={mapRef}></div>
            <div className="tooltip hidden" ref={tooltipRef}></div>

            <div className="map-footer">
                <p>Carte des produits laitiers - Bénin</p>
            </div>
        </div>
    );
}

export default MapThree;