import React, { useEffect, useRef, useState } from 'react';
import * as d3 from 'd3';
import { geoPath, geoMercator } from 'd3-geo';
import './MapStyles.css';

function MapTwo() {
    const mapRef = useRef(null);
    const tooltipRef = useRef(null);
    const [selectedSource, setSelectedSource] = useState('toutes');

    useEffect(() => {
        if (!mapRef.current) return;

        // Clear any existing SVG
        d3.select(mapRef.current).selectAll("*").remove();

        // Set up dimensions
        const width = 700;
        const height = 700;

        // Create SVG
        const svg = d3.select(mapRef.current)
            .append("svg")
            .attr("width", width)
            .attr("height", height);

        // Create tooltip
        const tooltip = d3.select(tooltipRef.current);

        // Set up projection for Benin
        const projection = geoMercator()
            .center([2.3, 9.5]) // Center of Benin
            .scale(5000)
            .translate([width / 2, height / 2]);

        // Set up path generator
        const path = geoPath().projection(projection);

        // Set up color scale
        const color = d3.scaleLinear()
            .domain([1, 10])
            .range(["#f7fcf5", "#00441b"]);

        // Set up zoom behavior
        const zoom = d3.zoom()
            .scaleExtent([1, 8])
            .on("zoom", (event) => {
                svg.selectAll("path")
                    .attr("transform", event.transform);
                svg.selectAll("circle")
                    .attr("transform", event.transform);
                svg.selectAll("text")
                    .attr("transform", event.transform);
            });

        // Apply zoom to SVG
        svg.call(zoom);

        // Sources data
        const sources = [
            { id: 0, name: 'INRAB', file: 'produits.geojson' },
            { id: 1, name: 'MAEP', file: 'produits.geojson' },
            { id: 2, name: 'INSAE', file: 'produits.geojson' }
        ];

        // Load data
        Promise.all([
            d3.json(process.env.PUBLIC_URL + '/json/benin/departements.geojson'),
            d3.json(process.env.PUBLIC_URL + '/json/benin/communes.geojson'),
            d3.json(process.env.PUBLIC_URL + '/json/benin/produits.geojson')
        ]).then(([departements, communes, produits]) => {
            // Draw departments (base map)
            svg.selectAll('.departement')
                .data(departements.features)
                .enter()
                .append('path')
                .attr("d", path)
                .attr("class", "fond")
                .attr("stroke", "#fff")
                .attr("stroke-width", 1);

            // Draw communes as polygons with color fills
            svg.selectAll('.commune-circle')
                .data(communes.features)
                .enter()
                .append('circle')
                .attr("cx", d => projection(d.geometry.coordinates)[0])
                .attr("cy", d => projection(d.geometry.coordinates)[1])
                .attr("r", 8)
                .attr("class", "lieux_aplat")
                .style("fill", function(d) {
                    const value = d.properties.nb_lieux;
                    if (value) {
                        return color(value);
                    } else {
                        return "#ccc";
                    }
                })
                .style("stroke", "#333")
                .style("stroke-width", 1);

            // Draw product points
            displayProductPoints(produits, svg, projection, tooltip, 'toutes');

        }).catch(error => {
            console.error("Error loading data:", error);
        });

        // Function to update product points based on selected source
        const updateProductPoints = (sourceName) => {
            // Remove existing product points
            svg.selectAll('.product-point').remove();
            svg.selectAll('.product-label').remove();

            d3.json(process.env.PUBLIC_URL + '/json/benin/produits.geojson')
                .then(data => {
                    displayProductPoints(data, svg, projection, tooltip, sourceName);
                })
                .catch(error => console.error("Error loading data:", error));
        };

        // Function to display product points
        function displayProductPoints(data, svg, projection, tooltip, sourceName) {
            // Filter data based on source if needed
            let filteredData = data.features;
            
            // In a real app, you would filter based on source
            // For this demo, we'll just use all data but simulate different symbols

            // Draw product points
            svg.selectAll('.product-point')
                .data(filteredData)
                .enter()
                .append("circle")
                .attr("cx", d => projection(d.geometry.coordinates)[0])
                .attr("cy", d => projection(d.geometry.coordinates)[1])
                .attr("r", 6)
                .attr("class", "product-point")
                .style("fill", function(d) {
                    // Different colors based on source
                    if (sourceName === 'INRAB') return "#1f77b4";
                    if (sourceName === 'MAEP') return "#ff7f0e";
                    if (sourceName === 'INSAE') return "#2ca02c";
                    return "#9467bd"; // Default for 'toutes'
                })
                .style("stroke", "#333")
                .style("stroke-width", 1)
                .style("opacity", 0.8)
                .on('mousemove', function(event, d) {
                    // Show tooltip
                    const [x, y] = d3.pointer(event);
                    
                    // Calculate total products
                    const totalProducts = Object.values(d.properties.produits).reduce((a, b) => a + b, 0);
                    
                    tooltip.classed('hidden', false)
                        .style('left', (x + 20) + 'px')
                        .style('top', (y + 20) + 'px')
                        .html(`
                            <strong>${d.properties.name}</strong><br>
                            Département: ${d.properties.departement}<br>
                            Total produits: ${totalProducts}<br>
                            Source: ${sourceName === 'toutes' ? 'Toutes sources' : sourceName}
                        `);
                })
                .on('mouseout', function() {
                    // Hide tooltip
                    tooltip.classed('hidden', true);
                });

            // Add commune labels
            svg.selectAll('.product-label')
                .data(filteredData)
                .enter()
                .append('text')
                .attr("x", d => projection(d.geometry.coordinates)[0])
                .attr("y", d => projection(d.geometry.coordinates)[1] - 10)
                .attr("text-anchor", "middle")
                .attr("class", "product-label")
                .style("font-size", "10px")
                .style("font-weight", "bold")
                .text(d => d.properties.name);
        }

        // Set up event listener for source change
        const handleSourceChange = (e) => {
            setSelectedSource(e.target.value);
            updateProductPoints(e.target.value);
        };

        // Expose the handler to the component
        window.handleSourceChange = handleSourceChange;

        // Cleanup function
        return () => {
            d3.select(mapRef.current).selectAll("*").remove();
            delete window.handleSourceChange;
        };
    }, []);

    return (
        <div className="map-page">
            <div className="map-title">
                <h2>Produits du terroir par source au Bénin</h2>
            </div>

            <div className="map-controls">
                <label htmlFor="sourceSelect">Source: </label>
                <select
                    id="sourceSelect"
                    value={selectedSource}
                    onChange={(e) => window.handleSourceChange && window.handleSourceChange(e)}
                >
                    <option value="toutes">Toutes sources</option>
                    <option value="INRAB">INRAB</option>
                    <option value="MAEP">MAEP</option>
                    <option value="INSAE">INSAE</option>
                </select>
            </div>

            <div className="map-container" ref={mapRef}></div>
            <div className="tooltip hidden" ref={tooltipRef}></div>

            <div className="map-footer">
                <p>Carte des produits du terroir par source - Bénin</p>
            </div>
        </div>
    );
}

export default MapTwo;